package com.qrid.servlet;
import com.qrid.dao.*;import com.qrid.model.*;import com.qrid.util.*;import org.apache.commons.csv.*;import javax.servlet.*;import javax.servlet.annotation.*;import javax.servlet.http.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.sql.Date;
@WebServlet("/admin/bulk-import") @MultipartConfig(maxFileSize=2097152,maxRequestSize=2621440) public class BulkImportServlet extends HttpServlet{
 protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{r.getRequestDispatcher("/WEB-INF/views/admin/bulk-import.jsp").forward(r,s);}
 protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{User u=(User)r.getSession().getAttribute("user");int ok=0,failed=0;StringBuilder errors=new StringBuilder();try{Part f=r.getPart("csv");if(f==null||f.getSize()==0||!f.getSubmittedFileName().toLowerCase().endsWith(".csv"))throw new IllegalArgumentException("Select a CSV file.");try(Reader in=new InputStreamReader(f.getInputStream(),StandardCharsets.UTF_8);CSVParser p=CSVFormat.DEFAULT.builder().setHeader().setSkipHeaderRecord(true).setTrim(true).build().parse(in)){for(CSVRecord rec:p){try{Identity x=new Identity();x.setIdentityNo(rec.get("identity_no"));x.setFullName(rec.get("full_name"));x.setEmail(rec.get("email"));x.setPersonType(rec.get("person_type").toUpperCase());x.setDepartment(rec.get("department"));x.setCourse(rec.get("course"));x.setStatus("ACTIVE");x.setValidFrom(Date.valueOf(rec.get("valid_from")));x.setValidUntil(Date.valueOf(rec.get("valid_until")));x.setQrToken(TokenUtil.generate());new IdentityDao().insert(x,null,null,u.getId());ok++;}catch(Exception row){failed++;if(errors.length()<500)errors.append("Row ").append(rec.getRecordNumber()+1).append(": ").append(row.getMessage()).append("; ");}}}new AuditDao().log(u.getId(),"BULK_IMPORT","IDENTITY","-",ok+" imported, "+failed+" failed",r.getRemoteAddr());Flash.set(r,failed==0?"success":"warning",ok+" identities imported; "+failed+" failed. "+errors);}catch(Exception e){Flash.set(r,"danger","Import failed: "+e.getMessage());}s.sendRedirect(r.getContextPath()+"/admin/bulk-import");}
}
